import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, FileText, Flame, Heart, Highlighter, Layers3, Link2, List, Loader2, LogOut, Menu, MoreHorizontal, Pencil, Plus, Quote, RotateCcw, Search, Settings2, Sparkles, Sun, Tag, Trash2, Upload, X } from 'lucide-react';
import { api, ApiError, list, patch, post, tagsFrom, type Category, type Highlight, type Page, type Settings, type Source } from './api';

type Route = 'Daily review' | 'Library' | 'Favorites' | 'Discards' | 'Integrations' | 'Settings';
type User = { id: string; name: string; email: string };
type Me = User | { user: User };
type Review = { date: string; cards: Highlight[]; completed: number | boolean; streak: number };
const routeIcons = { 'Daily review': Sun, Library: BookOpen, Favorites: Heart, Discards: Trash2, Integrations: Layers3, Settings: Settings2 };
const categories: Category[] = ['books', 'articles', 'tweets', 'podcasts', 'freeform'];
const categoryLabel = (category: string) => ({ books: 'Book', articles: 'Article', tweets: 'Tweet', podcasts: 'Podcast', freeform: 'Freeform' }[category] || category);
const initials = (value: string) => value.split(' ').map(s => s[0]).slice(0, 2).join('').toUpperCase();

function ErrorNotice({ error, retry }: { error: unknown; retry?: () => void }) { return <div className="error-notice" role="alert"><span>{error instanceof Error ? error.message : 'Something went wrong. Please try again.'}</span>{retry && <button onClick={retry}>Try again</button>}</div>; }
function Loading() { return <div className="loading"><Loader2 size={22} className="spin"/><span>Opening your library…</span></div>; }
function Empty({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="empty"><div className="empty-icon"><BookOpen size={28} strokeWidth={1.3}/></div><h2>{title}</h2><p>{description}</p>{action}</div>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { const previous = document.activeElement as HTMLElement; const el = ref.current; el?.querySelector<HTMLElement>('input, textarea, button, select')?.focus(); const key = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); if (event.key === 'Tab' && el) { const nodes = el.querySelectorAll<HTMLElement>('button:not(:disabled), input, textarea, select, a[href]'); const first = nodes[0]; const last = nodes[nodes.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } }; document.addEventListener('keydown', key); document.body.style.overflow = 'hidden'; return () => { document.removeEventListener('keydown', key); document.body.style.overflow = ''; previous?.focus(); }; }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div ref={ref} className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><div><h2 id="dialog-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={20}/></button></header>{children}</div></div>;
}
function Cover({ source, small = false }: { source?: Source; small?: boolean }) { return <div className={`cover ${small ? 'small' : ''} cover-${source?.category || 'freeform'}`}>{source?.coverUrl ? <img src={source.coverUrl} alt="" loading="lazy" onError={e => { e.currentTarget.style.display = 'none'; }}/>: <><span className="cover-kicker">{source?.author || categoryLabel(source?.category || 'freeform')}</span><span className="cover-title">{source?.title || 'Your words'}</span><span className="cover-mark">p.</span></>}</div>; }

function Auth({ onSuccess }: { onSuccess: () => void }) {
  const setup = useQuery({ queryKey: ['setup'], queryFn: () => api<{ required?: boolean; needsSetup?: boolean; setupRequired?: boolean }>('/setup'), retry: false });
  const required = setup.data?.required ?? setup.data?.needsSetup ?? setup.data?.setupRequired ?? false;
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const login = useMutation({ mutationFn: async () => { if (required) await post('/setup', { name, email, password }); else await post('/api/auth/sign-in/email', { email, password }); }, onSuccess });
  return <main className="auth"><div className="auth-story"><a className="wordmark" href="#">passage<span>✳</span></a><div><p className="eyebrow">A HOME FOR YOUR HIGHLIGHTS</p><h1>Good words deserve<br/>a second reading.</h1><p>Collect what moves you. Return to what matters.<br/>Let your best ideas grow roots.</p><div className="auth-drawing"><span/><BookOpen size={108} strokeWidth={.7}/><span/></div></div><p className="auth-footer">Your words. Your library. Your own little corner.</p></div><div className="auth-form"><div className="auth-mobile wordmark">passage<span>✳</span></div><p className="eyebrow">{required ? 'YOUR LIBRARY STARTS HERE' : 'A MOMENT FOR YOURSELF'}</p><h2>{required ? 'Make yourself at home.' : 'Welcome back.'}</h2><p className="muted">{required ? 'Create the owner account for this Passage instance.' : 'Sign in to pick up where you left off.'}</p>{setup.isLoading ? <Loading/> : <form onSubmit={e => { e.preventDefault(); login.mutate(); }}>{required && <label>Your name<input value={name} onChange={e => setName(e.target.value)} autoComplete="name" required placeholder="How should we call you?"/></label>}<label>Email address<input value={email} onChange={e => setEmail(e.target.value)} type="email" autoComplete="email" required placeholder="you@example.com"/></label><label>Password<input value={password} onChange={e => setPassword(e.target.value)} type="password" autoComplete={required ? 'new-password' : 'current-password'} minLength={8} required placeholder="At least 8 characters"/></label>{login.error && <ErrorNotice error={login.error}/>}<button className="primary full" disabled={login.isPending}>{login.isPending ? <Loader2 className="spin" size={17}/> : <>{required ? 'Create your library' : 'Enter your library'}<ArrowRight size={17}/></>}</button></form>}<p className="privacy"><span className="status-dot"/> Private by design. Self-hosted by you.</p></div></main>;
}

export default function App() {
  const client = useQueryClient();
  const me = useQuery({ queryKey: ['me'], queryFn: () => api<Me>('/me'), retry: false });
  const [route, setRoute] = useState<Route>('Library'); const [mobile, setMobile] = useState(false); const [capture, setCapture] = useState(false); const [editing, setEditing] = useState<Highlight | null>(null); const [sourceEdit, setSourceEdit] = useState<Source | null>(null); const [toast, setToast] = useState('');
  const sourcesQuery = useQuery({ queryKey: ['sources'], queryFn: () => api<Source[] | { items: Source[] }>('/sources'), enabled: !!me.data });
  const review = useQuery({ queryKey: ['review'], queryFn: () => api<Review>('/daily-review'), enabled: !!me.data });
  const sources = list(sourcesQuery.data);
  const notify = (message: string) => setToast(message);
  const refresh = () => { void client.invalidateQueries({ queryKey: ['highlights'] }); void client.invalidateQueries({ queryKey: ['sources'] }); void client.invalidateQueries({ queryKey: ['review'] }); };
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 4000); return () => clearTimeout(timer); } }, [toast]);
  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key === 'j') { e.preventDefault(); setCapture(true); } }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []);
  if (me.isLoading) return <Loading/>;
  if (me.error) { if (me.error instanceof ApiError && (me.error.status === 401 || me.error.status === 403)) return <Auth onSuccess={() => { void client.invalidateQueries({ queryKey: ['me'] }); }}/>; return <main className="connection-error"><div className="wordmark">passage<span>✳</span></div><h1>Couldn’t reach your library.</h1><p>Check that your Passage server is running, then try again.</p><ErrorNotice error={me.error} retry={() => { void me.refetch(); }}/></main>; }
  const user = me.data && ('user' in me.data ? me.data.user : me.data);
  const nav = (next: Route) => { setRoute(next); setMobile(false); };
  const reviewCount = review.data?.cards?.length || 0;
  return <div className="app-shell"><aside className={`sidebar ${mobile ? 'open' : ''}`}><a className="wordmark" href="#" onClick={e => { e.preventDefault(); nav('Library'); }}>passage<span>✳</span></a><p className="sidebar-caption">A little wisdom, kept close.</p><nav aria-label="Main navigation">{(['Daily review', 'Library', 'Favorites', 'Discards'] as Route[]).map(item => { const Icon = routeIcons[item]; return <button key={item} className={`nav-item ${route === item ? 'active' : ''}`} onClick={() => nav(item)}><Icon size={18} strokeWidth={1.6}/><span>{item}</span>{item === 'Daily review' && reviewCount > 0 && <span className="nav-count">{reviewCount}</span>}</button>; })}<div className="nav-divider"/>{(['Integrations', 'Settings'] as Route[]).map(item => { const Icon = routeIcons[item]; return <button className={`nav-item ${route === item ? 'active' : ''}`} key={item} onClick={() => nav(item)}><Icon size={18} strokeWidth={1.6}/><span>{item}</span></button>; })}</nav><div className="sidebar-bottom"><div className="quiet-note"><span>✳</span><p>What you read<br/>becomes part of you.</p></div><button className="profile" onClick={() => nav('Settings')}><span className="avatar">{initials(user?.name || 'Reader')}</span><span><strong>{user?.name || 'Your library'}</strong><small>Personal workspace</small></span><ChevronDown size={14}/></button></div></aside>{mobile && <button aria-label="Close navigation" className="nav-scrim" onClick={() => setMobile(false)}/>}<div className="workspace"><header className="topbar"><div className="breadcrumbs"><button className="icon-button mobile-menu" onClick={() => setMobile(true)} aria-label="Open navigation"><Menu size={20}/></button><span>Your workspace</span><ChevronRight size={13}/><strong>{route}</strong></div><div className="topbar-right"><span className="private-label"><span className="status-dot"/> Private library</span><button className="icon-button" aria-label="Help and keyboard shortcuts" onClick={() => notify('Press Ctrl / ⌘ + J to save a highlight. During review: → keep, ← skip, Delete discard.')}><CircleHelp size={17}/></button></div></header><main className="main-content">{route === 'Daily review' ? <ReviewPage review={review.data} loading={review.isLoading} error={review.error} sources={sources} refresh={refresh} notify={notify} edit={setEditing} capture={() => setCapture(true)}/> : route === 'Integrations' ? <Integrations notify={notify} refresh={refresh}/> : route === 'Settings' ? <SettingsPage user={user} notify={notify}/> : <Library route={route} sources={sources} sourceError={sourcesQuery.error} capture={() => setCapture(true)} edit={setEditing} sourceEdit={setSourceEdit} review={review.data} onReview={() => nav('Daily review')} refresh={refresh} notify={notify}/>}</main><footer className="workspace-footer"><span>Words worth keeping. Ideas worth returning to.</span><span>Made for a thoughtful life <span className="footer-star">✳</span></span></footer></div>{capture && <Capture sources={sources} onClose={() => setCapture(false)} onSuccess={() => { refresh(); setCapture(false); notify('Highlight saved to your library.'); }}/>} {editing && <HighlightEditor highlight={editing} source={sources.find(s => s.id === editing.sourceId)} onClose={() => setEditing(null)} onSuccess={message => { refresh(); setEditing(null); notify(message); }}/>} {sourceEdit && <SourceEditor source={sourceEdit} onClose={() => setSourceEdit(null)} onSuccess={message => { refresh(); setSourceEdit(null); notify(message); }}/>} {toast && <div className="toast" role="status"><Check size={17}/>{toast}<button className="icon-button" onClick={() => setToast('')} aria-label="Dismiss notification"><X size={14}/></button></div>}</div>;
}

function Library({ route, sources, sourceError, capture, edit, sourceEdit, review, onReview, refresh, notify }: { route: Route; sources: Source[]; sourceError: unknown; capture: () => void; edit: (h: Highlight) => void; sourceEdit: (s: Source) => void; review?: Review; onReview: () => void; refresh: () => void; notify: (m: string) => void }) {
  const [q, setQ] = useState(''); const [tab, setTab] = useState('all'); const [page, setPage] = useState(1); const [selected, setSelected] = useState<string[]>([]); const [bulk, setBulk] = useState(false); const [sort, setSort] = useState('newest'); const [tag, setTag] = useState('');
  const params = new URLSearchParams({ q, page: String(page), limit: '30', discarded: String(route === 'Discards') }); if (route === 'Favorites') params.set('favorite', 'true'); if (tag) params.set('tag', tag);
  const query = useQuery({ queryKey: ['highlights', route, q, page, tag], queryFn: () => api<Page>(`/highlights?${params}`) });
  useEffect(() => { setPage(1); setSelected([]); }, [q, tag, route]);
  const mutation = useMutation({ mutationFn: ({ id, value }: { id: string; value: Partial<Highlight> }) => patch(`/highlights/${id}`, value), onSuccess: refresh, onError: error => notify(error.message) });
  const highlights = (query.data?.items || []).filter(h => tab === 'all' || sources.find(s => s.id === h.sourceId)?.category === tab).sort((a, b) => sort === 'oldest' ? a.createdAt.localeCompare(b.createdAt) : b.createdAt.localeCompare(a.createdAt));
  const allTags = [...new Set((query.data?.items || []).flatMap(h => h.tags))].sort();
  return <><div className="page-heading"><div><p className="eyebrow">YOUR COLLECTION OF GOOD THINGS</p><h1>{route === 'Library' ? 'Your library' : route === 'Favorites' ? 'The ones that stay.' : 'Room for new ideas.'}<span className="heading-dot">.</span></h1><p>{route === 'Library' ? 'A home for the words that move you. Come back to them, often.' : route === 'Favorites' ? 'A personal collection of your most meaningful highlights.' : 'Highlights you’ve set aside. Bring them back whenever you like.'}</p></div><button className="primary" onClick={capture}><Plus size={17}/>Add highlight<kbd>⌘ J</kbd></button></div><div className="library-layout"><section className="library-main"><div className="search-row"><div className="search-field"><Search size={18}/><input aria-label="Search highlights" placeholder="Search your highlights, notes, and ideas…" value={q} onChange={e => setQ(e.target.value)}/>{q && <button className="icon-button" aria-label="Clear search" onClick={() => setQ('')}><X size={15}/></button>}<kbd>/</kbd></div><button className={`filter-button ${tag ? 'selected' : ''}`} aria-label="Filter by tag" onClick={() => document.getElementById('tag-filter')?.focus()}><Settings2 size={17}/><select id="tag-filter" aria-label="Tag filter" value={tag} onChange={e => setTag(e.target.value)}><option value="">Filter</option>{allTags.map(t => <option key={t} value={t}>{t}</option>)}</select></button></div><div className="tabs-row"><div className="tabs" role="tablist" aria-label="Source category">{[['all', 'All sources'], ['books', 'Books'], ['articles', 'Articles'], ['freeform', 'Freeform']].map(([id, label]) => <button role="tab" aria-selected={tab === id} key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}>{label}</button>)}<select aria-label="More source categories" value={['tweets', 'podcasts'].includes(tab) ? tab : ''} onChange={e => { if (e.target.value) setTab(e.target.value); }}><option value="">More</option><option value="tweets">Tweets</option><option value="podcasts">Podcasts</option></select></div></div><div className="list-meta"><span>{query.data?.total ?? '—'} highlights <span className="meta-dot">·</span> {sources.length} sources{tag && <> <span className="meta-dot">·</span> #{tag}</>}</span><select aria-label="Sort highlights" value={sort} onChange={e => setSort(e.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></div>{selected.length > 0 && <div className="bulk-bar"><span>{selected.length} selected</span><button onClick={() => setBulk(true)}><Tag size={14}/>Add tags</button><button onClick={() => setSelected([])}>Clear</button></div>}{sourceError && <ErrorNotice error={sourceError}/>} {query.isLoading ? <Loading/> : query.error ? <ErrorNotice error={query.error} retry={() => { void query.refetch(); }}/> : highlights.length ? <div className="highlight-list">{highlights.map(h => { const source = sources.find(s => s.id === h.sourceId) || h.source; return <article className="highlight-row" key={h.id}><div className="row-cover"><Cover source={source}/><label className="row-check"><input aria-label={`Select highlight from ${source?.title || 'source'}`} type="checkbox" checked={selected.includes(h.id)} onChange={e => setSelected(e.target.checked ? [...selected, h.id] : selected.filter(id => id !== h.id))}/></label></div><div className="highlight-content"><div className="source-line"><button onClick={() => source && sourceEdit(source)} className="source-title">{source?.title || 'Untitled source'}</button><span className="source-category">{categoryLabel(source?.category || 'freeform')}</span></div><p className="source-author">{source?.author || 'Your collection'}{h.location && <><span>·</span>{h.location}</>}</p><button className="quote-button" onClick={() => edit(h)}><blockquote>{h.text}</blockquote></button>{h.note && <p className="highlight-note"><Pencil size={12}/>{h.note}</p>}<div className="highlight-footer"><div className="tag-list">{h.tags.map(t => <button className="tag" key={t} onClick={() => setTag(t)}>{t}</button>)}{!h.tags.length && <button className="subtle add-tag" onClick={() => edit(h)}><Plus size={12}/>Add a tag</button>}</div><div className="row-actions"><span>{new Date(h.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</span><button className={`icon-button ${h.favorite ? 'favorited' : ''}`} onClick={() => mutation.mutate({ id: h.id, value: { favorite: !h.favorite } })} aria-label={h.favorite ? 'Remove from favorites' : 'Add to favorites'} aria-pressed={h.favorite}><Heart size={16} fill={h.favorite ? 'currentColor' : 'none'}/></button><button className="icon-button" onClick={() => { void navigator.clipboard.writeText(h.text).then(() => notify('Highlight copied.')).catch(() => notify('Could not access clipboard.')); }} aria-label="Copy highlight"><Copy size={15}/></button>{route === 'Discards' ? <button className="icon-button" onClick={() => mutation.mutate({ id: h.id, value: { discarded: false } })} aria-label="Restore highlight"><RotateCcw size={16}/></button> : <button className="icon-button" onClick={() => edit(h)} aria-label="Edit highlight"><MoreHorizontal size={18}/></button>}</div></div></div></article>; })}</div> : <Empty title={q || tab !== 'all' || tag ? 'No words found. Yet.' : route === 'Discards' ? 'A clean slate.' : route === 'Favorites' ? 'Keep your favorites close.' : 'Every library starts with a line.'} description={q || tab !== 'all' || tag ? 'Try another search or remove a filter to find your highlights.' : route === 'Discards' ? 'Highlights you discard will appear here, ready to restore.' : route === 'Favorites' ? 'Tap the heart on any highlight to find it here.' : 'Save a passage from a book, an article, or your own wandering thoughts.'} action={route === 'Library' && <button className="primary" onClick={capture}><Plus size={16}/>Save your first highlight</button>}/>} {query.data && query.data.total > 30 && <div className="pagination"><button disabled={page === 1} onClick={() => setPage(page - 1)}><ChevronLeft size={16}/>Previous</button><span>Page {page} of {Math.ceil(query.data.total / 30)}</span><button disabled={page * 30 >= query.data.total} onClick={() => setPage(page + 1)}>Next<ChevronRight size={16}/></button></div>}</section><aside className="reading-aside"><div className="daily-panel"><div className="panel-label"><Sun size={18}/><span>A LITTLE EVERY DAY</span></div><h2>Meet your ideas<br/>again.</h2><p>A few familiar words.<br/>A fresh way to see them.</p><div className="review-progress"><div className="progress-circle"><span>{review?.cards?.length ?? '—'}</span></div><div><strong>highlights for today</strong><small>Your daily pause for thought</small></div></div><button className="primary full" onClick={onReview}>Begin daily review<ArrowRight size={16}/></button><p className="panel-foot"><Clock3 size={12}/>About {Math.max(1, Math.ceil((review?.cards?.length || 0) / 3))} minutes. All yours.</p></div><div className="library-note"><span className="quote-symbol">“</span><p>Reading gives us someplace to go when we have to stay where we are.</p><span className="quote-attribution">MASON COOLEY</span></div><div className="collection-stats"><div><BookOpen size={15}/><span>Your sources</span><strong>{sources.length}</strong></div><div><Highlighter size={15}/><span>Saved highlights</span><strong>{query.data?.total ?? '—'}</strong></div><div><Flame size={15}/><span>Review streak</span><strong>{review?.streak ?? 0} days</strong></div></div><button className="aside-link" onClick={capture}><Plus size={15}/>A good thought? Keep it.</button></aside></div>{bulk && <BulkTags ids={selected} onClose={() => setBulk(false)} onSuccess={() => { refresh(); setBulk(false); setSelected([]); notify('Tags added to selected highlights.'); }}/>}</>;
}

function Capture({ sources, onClose, onSuccess }: { sources: Source[]; onClose: () => void; onSuccess: () => void }) {
  const [sourceId, setSourceId] = useState(sources[0]?.id || 'new'); const [text, setText] = useState(''); const [note, setNote] = useState(''); const [tags, setTags] = useState(''); const [location, setLocation] = useState(''); const [title, setTitle] = useState(''); const [author, setAuthor] = useState(''); const [category, setCategory] = useState<Category>('books'); const [url, setUrl] = useState('');
  const save = useMutation({ mutationFn: async () => { let id = sourceId; if (id === 'new') { const source = await post<Source>('/sources', { title, author: author || null, category, sourceUrl: url || null, tags: [] }); id = source.id; } await post('/highlights', { sourceId: id, text, note: note || null, tags: tagsFrom(tags), location: location || null }); }, onSuccess });
  return <Modal title="Keep a good thought." subtitle="A little piece of something worth remembering." onClose={onClose}><form onSubmit={e => { e.preventDefault(); save.mutate(); }}><label>Passage<textarea className="capture-text" value={text} onChange={e => setText(e.target.value)} placeholder="The words that made you stop…" required rows={4}/></label><label>From your library<select value={sourceId} onChange={e => setSourceId(e.target.value)}>{sources.map(s => <option key={s.id} value={s.id}>{s.title}{s.author ? ` — ${s.author}` : ''}</option>)}<option value="new">＋ Add a new source</option></select></label>{sourceId === 'new' && <div className="new-source-fields"><div className="form-grid"><label>Source title<input value={title} onChange={e => setTitle(e.target.value)} placeholder="Book, article, or a thought" required/></label><label>Type<select value={category} onChange={e => setCategory(e.target.value as Category)}>{categories.map(c => <option key={c} value={c}>{categoryLabel(c)}</option>)}</select></label></div><div className="form-grid"><label>Author <span>optional</span><input value={author} onChange={e => setAuthor(e.target.value)} placeholder="Who wrote it?"/></label><label>Source URL <span>optional</span><input type="url" value={url} onChange={e => setUrl(e.target.value)} placeholder="https://…"/></label></div></div>}<label>Your note <span>optional</span><textarea value={note} onChange={e => setNote(e.target.value)} rows={2} placeholder="What did this stir in you?"/></label><div className="form-grid"><label>Tags <span>comma separated</span><input value={tags} onChange={e => setTags(e.target.value)} placeholder="creativity, a good life"/></label><label>Location <span>optional</span><input value={location} onChange={e => setLocation(e.target.value)} placeholder="Page 42, chapter 3…"/></label></div>{save.error && <ErrorNotice error={save.error}/>}<div className="modal-footer"><span><span className="status-dot"/>Saved only to your library</span><button className="primary" disabled={save.isPending}>{save.isPending ? <Loader2 className="spin" size={16}/> : <Check size={16}/>}Save highlight</button></div></form></Modal>;
}

function HighlightEditor({ highlight, source, onClose, onSuccess }: { highlight: Highlight; source?: Source; onClose: () => void; onSuccess: (m: string) => void }) {
  const [text, setText] = useState(highlight.text); const [note, setNote] = useState(highlight.note || ''); const [tags, setTags] = useState(highlight.tags.join(', ')); const [location, setLocation] = useState(highlight.location || ''); const [confirmDelete, setConfirmDelete] = useState(false);
  const save = useMutation({ mutationFn: () => patch(`/highlights/${highlight.id}`, { text, note: note || null, tags: tagsFrom(tags), location: location || null }), onSuccess: () => onSuccess('Your highlight is updated.') });
  const discard = useMutation({ mutationFn: () => patch(`/highlights/${highlight.id}`, { discarded: !highlight.discarded }), onSuccess: () => onSuccess(highlight.discarded ? 'Highlight restored to your library.' : 'Highlight moved to discards.') });
  const remove = useMutation({ mutationFn: () => api(`/highlights/${highlight.id}`, { method: 'DELETE' }), onSuccess: () => onSuccess('Highlight permanently deleted.') });
  return <Modal title="A thought, in focus." subtitle={`${source?.title || 'Your highlight'}${source?.author ? ` · ${source.author}` : ''}`} onClose={onClose}><form onSubmit={e => { e.preventDefault(); save.mutate(); }}><label>Passage<textarea className="capture-text" value={text} onChange={e => setText(e.target.value)} required rows={5}/></label><label>Your note<textarea value={note} onChange={e => setNote(e.target.value)} placeholder="A thought of your own…" rows={3}/></label><div className="form-grid"><label>Tags<input value={tags} onChange={e => setTags(e.target.value)} placeholder="Comma separated"/></label><label>Location<input value={location} onChange={e => setLocation(e.target.value)}/></label></div>{(save.error || discard.error || remove.error) && <ErrorNotice error={save.error || discard.error || remove.error}/>}<div className="modal-footer"><button type="button" className="text-button danger" disabled={discard.isPending} onClick={() => discard.mutate()}>{highlight.discarded ? <RotateCcw size={15}/> : <Trash2 size={15}/>} {highlight.discarded ? 'Restore highlight' : 'Discard highlight'}</button><button className="primary" disabled={save.isPending}><Check size={16}/>Save changes</button></div>{highlight.discarded && <div className="delete-zone">{confirmDelete ? <><span>This cannot be undone.</span><button type="button" className="text-button danger" onClick={() => remove.mutate()} disabled={remove.isPending}>Yes, delete permanently</button><button type="button" className="text-button" onClick={() => setConfirmDelete(false)}>Cancel</button></> : <button type="button" className="text-button danger" onClick={() => setConfirmDelete(true)}>Permanently delete</button>}</div>}</form></Modal>;
}

function SourceEditor({ source, onClose, onSuccess }: { source: Source; onClose: () => void; onSuccess: (m: string) => void }) {
  const [title, setTitle] = useState(source.title); const [author, setAuthor] = useState(source.author || ''); const [category, setCategory] = useState(source.category); const [url, setUrl] = useState(source.sourceUrl || ''); const [cover, setCover] = useState(source.coverUrl || ''); const [note, setNote] = useState(source.note || ''); const [tags, setTags] = useState(source.tags.join(', ')); const [weight, setWeight] = useState(source.weight ?? 1); const [deleting, setDeleting] = useState(false);
  const save = useMutation({ mutationFn: () => patch(`/sources/${source.id}`, { title, author: author || null, category, sourceUrl: url || null, coverUrl: cover || null, note: note || null, tags: tagsFrom(tags), weight }), onSuccess: () => onSuccess('Source details updated.') });
  const remove = useMutation({ mutationFn: () => api(`/sources/${source.id}`, { method: 'DELETE' }), onSuccess: () => onSuccess('Source and its highlights deleted.') });
  return <Modal title="Behind the words." subtitle="Give this source its proper place in your library." onClose={onClose}><form onSubmit={e => { e.preventDefault(); save.mutate(); }}><label>Title<input value={title} onChange={e => setTitle(e.target.value)} required/></label><div className="form-grid"><label>Author<input value={author} onChange={e => setAuthor(e.target.value)}/></label><label>Category<select value={category} onChange={e => setCategory(e.target.value as Category)}>{categories.map(c => <option value={c} key={c}>{categoryLabel(c)}</option>)}</select></label></div><label>Source URL<input type="url" value={url} onChange={e => setUrl(e.target.value)}/></label><label>Cover image URL<input type="url" value={cover} onChange={e => setCover(e.target.value)}/></label><label>Source note<textarea value={note} onChange={e => setNote(e.target.value)} rows={2}/></label><div className="form-grid"><label>Tags<input value={tags} onChange={e => setTags(e.target.value)}/></label><label>Review weight<input type="number" min="0" max="10" step="0.1" value={weight} onChange={e => setWeight(Number(e.target.value))}/></label></div><p className="field-help">Higher weight brings this source into your reviews more often. Set 0 to pause it.</p>{(save.error || remove.error) && <ErrorNotice error={save.error || remove.error}/>}<div className="modal-footer"><button type="button" className="text-button danger" onClick={() => setDeleting(true)}><Trash2 size={14}/>Delete source</button><button className="primary" disabled={save.isPending}>Save source</button></div>{deleting && <div className="delete-zone"><p>Delete this source and all its highlights? This cannot be undone.</p><button type="button" className="text-button danger" disabled={remove.isPending} onClick={() => remove.mutate()}>Delete source and highlights</button><button type="button" className="text-button" onClick={() => setDeleting(false)}>Cancel</button></div>}</form></Modal>;
}

function BulkTags({ ids, onClose, onSuccess }: { ids: string[]; onClose: () => void; onSuccess: () => void }) { const [tags, setTags] = useState(''); const save = useMutation({ mutationFn: async () => { const highlights = await api<Page>('/highlights?limit=10000&discarded=all'); const originals = highlights.items || []; for (const id of ids) { const h = originals.find(item => item.id === id); await patch(`/highlights/${id}`, { tags: [...new Set([...(h?.tags || []), ...tagsFrom(tags)])] }); } }, onSuccess }); return <Modal title={`Tag ${ids.length} highlights`} subtitle="Add a common thread without removing existing tags." onClose={onClose}><form onSubmit={e => { e.preventDefault(); save.mutate(); }}><label>Tags<input value={tags} onChange={e => setTags(e.target.value)} placeholder="creativity, life lessons" required/></label>{save.error && <ErrorNotice error={save.error}/>}<div className="modal-footer"><span>Separate tags with commas.</span><button className="primary" disabled={save.isPending}>Add tags</button></div></form></Modal>; }

function ReviewPage({ review, loading, error, sources, refresh, notify, edit, capture }: { review?: Review; loading: boolean; error: unknown; sources: Source[]; refresh: () => void; notify: (m: string) => void; edit: (h: Highlight) => void; capture: () => void }) {
  const [mode, setMode] = useState<'cards' | 'list'>('cards'); const [index, setIndex] = useState(0); const [handled, setHandled] = useState<string[]>([]);
  const remaining = (review?.cards || []).filter(h => !handled.includes(h.id)); const card = remaining[index % Math.max(remaining.length, 1)]; const source = sources.find(s => s.id === card?.sourceId) || card?.source;
  const respond = useMutation({ mutationFn: ({ id, action }: { id: string; action: string }) => post(`/daily-review/${id}`, { action }), onSuccess: (_, variables) => { setHandled(previous => [...previous, variables.id]); setIndex(0); refresh(); }, onError: err => notify(err.message) });
  useEffect(() => { const onKey = (e: KeyboardEvent) => { if (!card || respond.isPending || ['INPUT', 'TEXTAREA', 'SELECT'].includes((e.target as HTMLElement)?.tagName) || document.querySelector('[role="dialog"]')) return; const action = e.key === 'ArrowRight' ? 'keep' : e.key === 'ArrowLeft' ? 'skip' : e.key === 'Delete' ? 'discard' : null; if (action) { e.preventDefault(); respond.mutate({ id: card.id, action }); } }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, [card, respond]);
  return <><div className="page-heading"><div><p className="eyebrow">A SMALL RITUAL. A LASTING IMPRESSION.</p><h1>Your daily review<span className="heading-dot">.</span></h1><p>Return to the words you kept. See what they mean today.</p></div><div className="view-toggle" aria-label="Review view"><button className={mode === 'cards' ? 'active' : ''} onClick={() => setMode('cards')} aria-label="Card view"><Layers3 size={17}/></button><button className={mode === 'list' ? 'active' : ''} onClick={() => setMode('list')} aria-label="List view"><List size={17}/></button></div></div>{loading ? <Loading/> : error ? <ErrorNotice error={error} retry={refresh}/> : !card ? <Empty title={sources.length ? 'A little wiser. A little lighter.' : 'Plant your first idea.'} description={sources.length ? 'Your review is complete. Let these words settle in, and come back for another tomorrow.' : 'Save a few highlights, then return here to make them part of you.'} action={<button className="primary" onClick={capture}><Plus size={16}/>Keep another thought</button>}/> : <><div className="review-topline"><span><Sun size={17}/>{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span><span><Flame size={15}/>{review?.streak || 0} day streak</span></div><div className="review-track"><div style={{ width: `${handled.length / Math.max(handled.length + remaining.length, 1) * 100}%` }}/></div>{mode === 'cards' ? <div className="review-card"><Quote className="review-quote-icon" size={30} strokeWidth={1}/><blockquote>{card.text}</blockquote><div className="review-source"><Cover source={source} small/><div><strong>{source?.title || 'Your collection'}</strong><p>{source?.author || 'A saved thought'}{card.location && ` · ${card.location}`}</p></div></div>{card.note && <div className="review-note"><Pencil size={14}/><p>{card.note}</p></div>}<div className="review-card-tags">{card.tags.map(t => <span className="tag" key={t}>{t}</span>)}<button className="text-button" onClick={() => edit(card)}><Pencil size={13}/>Add a thought</button></div></div> : <div className="review-list">{remaining.map(h => <article key={h.id}><blockquote>{h.text}</blockquote><p>{sources.find(s => s.id === h.sourceId)?.title || 'Your collection'}</p><div><button onClick={() => respond.mutate({ id: h.id, action: 'skip' })} disabled={respond.isPending}>Skip</button><button onClick={() => respond.mutate({ id: h.id, action: 'discard' })} disabled={respond.isPending}>Discard</button><button className="primary" onClick={() => respond.mutate({ id: h.id, action: 'keep' })} disabled={respond.isPending}><Check size={14}/>Keep</button></div></article>)}</div>}{mode === 'cards' && <div className="review-actions"><button className="secondary" disabled={respond.isPending} onClick={() => respond.mutate({ id: card.id, action: 'discard' })}><Trash2 size={16}/>Discard<kbd>del</kbd></button><button className="secondary" disabled={respond.isPending} onClick={() => respond.mutate({ id: card.id, action: 'skip' })}><ArrowLeft size={16}/>Skip for today<kbd>←</kbd></button><button className="primary" disabled={respond.isPending} onClick={() => respond.mutate({ id: card.id, action: 'keep' })}>{respond.isPending ? <Loader2 className="spin" size={16}/> : <Check size={16}/>}Keep with me<kbd>→</kbd></button></div>}<p className="review-bottom">{remaining.length} {remaining.length === 1 ? 'thought' : 'thoughts'} left. No rush. Good ideas deserve a moment.</p></>}</>;
}

function SettingsPage({ user, notify }: { user?: User; notify: (message: string) => void }) {
  const query = useQuery({ queryKey: ['settings'], queryFn: () => api<Settings>('/settings') }); const client = useQueryClient(); const [timezone, setTimezone] = useState(''); const [size, setSize] = useState(5); const [frequency, setFrequency] = useState('daily');
  useEffect(() => { if (query.data) { setTimezone(query.data.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone); setSize(query.data.reviewSize || 5); setFrequency(query.data.reviewFrequency || 'daily'); } }, [query.data]);
  const save = useMutation({ mutationFn: () => patch('/settings', { timezone, reviewSize: size, reviewFrequency: frequency }), onSuccess: () => { void client.invalidateQueries({ queryKey: ['settings'] }); void client.invalidateQueries({ queryKey: ['review'] }); notify('Your reading rhythm is saved.'); } });
  const logout = useMutation({ mutationFn: () => post('/api/auth/sign-out', {}), onSuccess: () => { client.clear(); location.reload(); }, onError: e => notify(e.message) });
  return <><div className="page-heading"><div><p className="eyebrow">MAKE ROOM FOR WHAT MATTERS</p><h1>Your own rhythm<span className="heading-dot">.</span></h1><p>A few preferences to make Passage feel more like you.</p></div></div><div className="settings-layout"><section className="settings-section"><div className="section-label"><Sun size={20}/><div><h2>Daily review</h2><p>A small habit, shaped around your day.</p></div></div>{query.isLoading ? <Loading/> : query.error ? <ErrorNotice error={query.error} retry={() => { void query.refetch(); }}/> : <form onSubmit={e => { e.preventDefault(); save.mutate(); }}><label>Time zone<input value={timezone} onChange={e => setTimezone(e.target.value)} list="timezones" placeholder="Asia/Kolkata" required/><datalist id="timezones">{['Asia/Kolkata', 'UTC', 'America/New_York', 'America/Los_Angeles', 'Europe/London', 'Europe/Berlin', 'Australia/Sydney'].map(t => <option key={t} value={t}/>)}</datalist></label><p className="field-help">Your daily review resets at midnight in this time zone.</p><div className="form-grid"><label>Highlights per review<input type="number" min="1" max="50" value={size} onChange={e => setSize(Number(e.target.value))}/></label><label>Review frequency<select value={frequency} onChange={e => setFrequency(e.target.value)}><option value="daily">Every day</option><option value="weekdays">Weekdays</option><option value="weekly">Once a week</option></select></label></div>{save.error && <ErrorNotice error={save.error}/>}<button className="primary" disabled={save.isPending}>{save.isPending ? <Loader2 size={15} className="spin"/> : <Check size={15}/>}Save preferences</button></form>}</section><section className="settings-section"><div className="section-label"><BookOpen size={20}/><div><h2>Your account</h2><p>This library belongs to you.</p></div></div><div className="account-line"><span className="avatar">{initials(user?.name || 'R')}</span><div><strong>{user?.name}</strong><p>{user?.email}</p></div></div><button className="secondary" disabled={logout.isPending} onClick={() => logout.mutate()}><LogOut size={15}/>Sign out</button></section><section className="settings-section"><div className="section-label"><ArrowDownToLine size={20}/><div><h2>Your words, always yours</h2><p>Take your entire library wherever you go.</p></div></div><div className="export-options">{['json', 'csv', 'markdown'].map(format => <a className="secondary" key={format} href={`/api/v1/export?format=${format}`} download><ArrowDownToLine size={15}/>{format === 'json' ? 'JSON' : format === 'csv' ? 'CSV' : 'Markdown'}</a>)}</div><p className="field-help">Exports include sources, highlights, notes, and tags.</p></section><ThemeSettings notify={notify}/></div></>;
}

type Integration = { id: string; provider?: string; name?: string; status: string; lastSyncedAt?: string; lastSyncAt?: string; error?: string };
function Integrations({ notify, refresh }: { notify: (message: string) => void; refresh: () => void }) {
  const query = useQuery({ queryKey: ['integrations'], queryFn: () => api<Integration[] | { items: Integration[] }>('/integrations') }); const client = useQueryClient(); const [notion, setNotion] = useState(false); const [token, setToken] = useState(''); const [databaseId, setDatabaseId] = useState(''); const [importing, setImporting] = useState(false);
  const connect = useMutation({ mutationFn: () => post('/integrations/notion', { token, databaseId }), onSuccess: () => { void client.invalidateQueries({ queryKey: ['integrations'] }); setNotion(false); setToken(''); notify('Notion configuration saved. Check the sync status below.'); } });
  const integrations = list(query.data);
  const notionStatus = integrations.find(i => (i.provider || i.name)?.toLowerCase() === 'notion');
  return <><div className="page-heading"><div><p className="eyebrow">ALL YOUR GOOD WORDS. ONE QUIET HOME.</p><h1>Bring it all together<span className="heading-dot">.</span></h1><p>Connect the places you read. Keep your ideas close.</p></div></div><div className="integration-intro"><div><span className="eyebrow">A LIBRARY WITHOUT WALLS</span><h2>Your reading life,<br/>a little more connected.</h2><p>Import a collection, save from your browser,<br/>or send your highlights to the tools you love.</p></div><div className="integration-art"><BookOpen size={42} strokeWidth={1}/><span/><Layers3 size={33} strokeWidth={1}/><span/><Quote size={35} strokeWidth={1}/></div></div>{query.error && <ErrorNotice error={query.error} retry={() => { void query.refetch(); }}/>}<div className="integration-list"><article><div className="integration-logo notion-logo">N</div><div><h3>Notion</h3><p>Sync highlights to a database in your workspace.</p>{notionStatus && <small className="integration-status"><span className={notionStatus.status === 'connected' ? 'status-dot' : 'status-dot pending'}/>{notionStatus.status}{(notionStatus.lastSyncedAt || notionStatus.lastSyncAt) && ` · Last sync ${new Date(notionStatus.lastSyncedAt || notionStatus.lastSyncAt || '').toLocaleString()}`}{notionStatus.error && ` · ${notionStatus.error}`}</small>}</div><button className="secondary" onClick={() => setNotion(true)}>{notionStatus ? 'Configure' : 'Connect'}<ArrowRight size={14}/></button></article><article><div className="integration-logo"><Upload size={24} strokeWidth={1.3}/></div><div><h3>Import your highlights</h3><p>Readwise CSV, Kindle clippings, or a Passage backup.</p></div><button className="secondary" onClick={() => setImporting(true)}>Import<ArrowRight size={14}/></button></article><article><div className="integration-logo"><ArrowDownToLine size={24} strokeWidth={1.3}/></div><div><h3>Portable by nature</h3><p>Download your library. Every highlight, note, and tag.</p></div><a className="secondary" href="/api/v1/export?format=json" download>Export JSON<ArrowDownToLine size={14}/></a></article><article><div className="integration-logo"><Link2 size={24} strokeWidth={1.3}/></div><div><h3>Browser extension</h3><p>Save selected text straight into Passage.</p><small>Load the extension from this repository’s apps/extension folder, then set your Passage URL in its options.</small></div><span className="availability">Included with self-hosting</span></article></div><p className="integration-footer"><span className="status-dot"/>Your connections. Your credentials. Stored on your own server.</p>{notion && <Modal title="A bridge to Notion." subtitle="Create an internal Notion integration and share your database with it." onClose={() => setNotion(false)}><form onSubmit={e => { e.preventDefault(); connect.mutate(); }}><label>Integration token<input type="password" value={token} onChange={e => setToken(e.target.value)} placeholder="ntn_… or secret_…" required autoComplete="off"/></label><label>Database ID<input value={databaseId} onChange={e => setDatabaseId(e.target.value)} placeholder="Your Notion database ID" required/></label><p className="field-help">Your integration needs access to read and insert pages in the selected database. Passage will validate access before connecting.</p>{connect.error && <ErrorNotice error={connect.error}/>}<div className="modal-footer"><button className="text-button" type="button" onClick={() => setNotion(false)}>Cancel</button><button className="primary" disabled={connect.isPending}>{connect.isPending && <Loader2 className="spin" size={15}/>}Save connection</button></div></form></Modal>}{importing && <ImportDialog onClose={() => setImporting(false)} onSuccess={() => { setImporting(false); refresh(); notify('Your collection is now part of Passage.'); }}/>}</>;
}

type ImportPreview = { previewId: string; total?: number; count?: number; duplicates?: number; duplicateCount?: number; errors?: (string | { message: string; row?: number })[]; items?: { text: string; title?: string; sourceTitle?: string }[]; highlights?: { text: string; title?: string }[]; stats?: { total?: number; duplicates?: number; valid?: number } };
function ImportDialog({ onClose, onSuccess }: { onClose: () => void; onSuccess: () => void }) {
  const [format, setFormat] = useState('readwise'); const [content, setContent] = useState(''); const [filename, setFilename] = useState(''); const [preview, setPreview] = useState<ImportPreview | null>(null); const [fileError, setFileError] = useState('');
  const inspect = useMutation({ mutationFn: () => post<ImportPreview>('/imports/preview', { format, content }), onSuccess: setPreview }); const commit = useMutation({ mutationFn: () => post('/imports/commit', { previewId: preview?.previewId }), onSuccess });
  return <Modal title={preview ? 'A look before you bring it in.' : 'Let your collection come home.'} subtitle={preview ? 'Check your import. Duplicate highlights are safely skipped.' : 'Start with a file or paste its contents. You’ll preview everything first.'} onClose={onClose} wide><form onSubmit={e => { e.preventDefault(); if (preview) commit.mutate(); else inspect.mutate(); }}>{!preview ? <><label>Import format<select value={format} onChange={e => setFormat(e.target.value)}><option value="readwise">Readwise CSV</option><option value="kindle">Kindle — My Clippings.txt</option><option value="json">Passage JSON backup</option><option value="csv">Passage CSV</option></select></label><label className="file-drop"><Upload size={24}/><strong>{filename || 'Choose an export file'}</strong><span>CSV, TXT, or JSON</span><input aria-label="Choose import file" type="file" accept=".csv,.txt,.json" onChange={async e => { const file = e.target.files?.[0]; if (file) { if (file.size > 20_000_000) { setFileError('Choose a file smaller than 20 MB.'); return; } setFileError(''); setFilename(file.name); setContent(await file.text()); } }}/></label><label>Or paste file contents<textarea value={content} onChange={e => setContent(e.target.value)} rows={5} placeholder="Your exported highlights…" required/></label>{fileError && <ErrorNotice error={new Error(fileError)}/>}</> : <div className="import-preview"><div className="import-stats"><div><strong>{preview.total ?? preview.count ?? preview.stats?.total ?? preview.items?.length ?? preview.highlights?.length ?? '—'}</strong><span>highlights found</span></div><div><strong>{preview.duplicates ?? preview.duplicateCount ?? preview.stats?.duplicates ?? 0}</strong><span>duplicates skipped</span></div><div><strong>{preview.errors?.length ?? 0}</strong><span>rows to check</span></div></div>{(preview.items || preview.highlights || []).slice(0, 5).map((item, i) => <div className="preview-row" key={i}><p>{item.text}</p><small>{'sourceTitle' in item ? String(item.sourceTitle || item.title || '') : item.title}</small></div>)}{preview.errors?.length ? <div className="import-errors"><strong>Some rows need attention</strong>{preview.errors.slice(0, 10).map((error, i) => <p key={i}>{typeof error === 'string' ? error : `${error.row ? `Row ${error.row}: ` : ''}${error.message}`}</p>)}</div> : null}</div>}{(inspect.error || commit.error) && <ErrorNotice error={inspect.error || commit.error}/>}<div className="modal-footer"><button className="text-button" type="button" onClick={() => preview ? setPreview(null) : onClose()}>{preview ? <><ArrowLeft size={14}/>Back</> : 'Cancel'}</button><button className="primary" disabled={inspect.isPending || commit.isPending || !content.trim()}>{(inspect.isPending || commit.isPending) && <Loader2 size={16} className="spin"/>}{preview ? 'Import collection' : 'Preview import'}<ArrowRight size={15}/></button></div></form></Modal>;
}

function ThemeSettings({ notify }: { notify: (message: string) => void }) {
  const client = useQueryClient(); const query = useQuery({ queryKey: ['themes'], queryFn: () => api<{ id: string; name: string; background?: string; color?: string }[] | { items: { id: string; name: string }[] }>('/themes') }); const [name, setName] = useState(''); const [background, setBackground] = useState('#285548'); const [color, setColor] = useState('#faf9f6');
  const save = useMutation({ mutationFn: () => post('/themes', { name, background, color }), onSuccess: () => { void client.invalidateQueries({ queryKey: ['themes'] }); setName(''); notify('Your card theme is saved.'); } });
  return <section className="settings-section"><div className="section-label"><Sparkles size={20}/><div><h2>Quote card themes</h2><p>A little color for words worth sharing.</p></div></div><div className="theme-swatches">{list(query.data).map(theme => <span key={theme.id} className="theme-chip">{theme.name}</span>)}</div><form onSubmit={(e: FormEvent) => { e.preventDefault(); save.mutate(); }}><div className="theme-inputs"><label>Theme name<input value={name} onChange={e => setName(e.target.value)} required placeholder="Forest & paper"/></label><label>Background<input aria-label="Theme background" type="color" value={background} onChange={e => setBackground(e.target.value)}/></label><label>Text<input aria-label="Theme text color" type="color" value={color} onChange={e => setColor(e.target.value)}/></label></div>{save.error && <ErrorNotice error={save.error}/>}<button className="secondary" disabled={save.isPending}><Plus size={14}/>Save theme</button></form></section>;
}
